/**
 * useExportExcel — generic hook for exporting tabular data to Excel (.xlsx)
 *
 * Usage:
 *   const { exportExcel, exporting } = useExportExcel();
 *   exportExcel({ fileName: 'BaoCaoHangNgay', sheetName: 'Sheet1', columns, rows });
 *
 * columns: { key: string; label: string; width?: number }[]
 * rows:    Record<string, string | number | boolean | null | undefined>[]
 */
import { useState, useCallback } from 'react';
import * as XLSX from 'xlsx';

export interface ExcelColumn {
  key:    string;
  label:  string;
  /** column width in characters. Default 18. */
  width?: number;
}

export interface ExportExcelOptions {
  fileName:   string;
  sheetName?: string;
  columns:    ExcelColumn[];
  rows:       Record<string, string | number | boolean | null | undefined>[];
}

export function useExportExcel() {
  const [exporting, setExporting] = useState(false);

  const exportExcel = useCallback((opts: ExportExcelOptions) => {
    const { fileName, sheetName = 'Sheet1', columns, rows } = opts;
    setExporting(true);

    try {
      // Header row
      const headerRow = columns.map((c) => c.label);

      // Data rows
      const dataRows = rows.map((row) =>
        columns.map((c) => {
          const v = row[c.key];
          return v === null || v === undefined ? '' : v;
        }),
      );

      const wsData = [headerRow, ...dataRows];
      const ws = XLSX.utils.aoa_to_sheet(wsData);

      // Set column widths
      ws['!cols'] = columns.map((c) => ({ wch: c.width ?? 18 }));

      // Style header row bold (basic)
      const range = XLSX.utils.decode_range(ws['!ref'] ?? 'A1');
      for (let col = range.s.c; col <= range.e.c; col++) {
        const cellRef = XLSX.utils.encode_cell({ r: 0, c: col });
        if (!ws[cellRef]) continue;
        ws[cellRef].s = { font: { bold: true } };
      }

      const wb = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, sheetName);

      const timestamp = new Date().toISOString().slice(0, 10);
      XLSX.writeFile(wb, `${fileName}_${timestamp}.xlsx`);
    } finally {
      setExporting(false);
    }
  }, []);

  return { exportExcel, exporting };
}
